// spec: .qa/e2e/specs/match-mutual.md 1.8 · кейс .qa/tests/match-mutual/MATCH-08.md
import { test, expect } from '../../fixtures';
import { captureApi, fullMatchId, messageTextKey, restPost, restDelete, qaText, type Api } from '../_shared/api';
import { saveSession } from '../_shared/session';

const DELETED_MATCH = '45786ffa'; // мэтч free с удалённой user3

test.describe('Взаимный матч (сервер)', () => {
  test('Мэтч с удалённым аккаунтом — отправка 403 @iphone @data (#b76c3b)', async ({ asUser }) => {
    const free = await asUser('free');
    const created: string[] = [];
    let a: Api | undefined;
    try {
      a = await captureApi(free);
      const matchId = await fullMatchId(a, DELETED_MATCH);
      const textKey = await messageTextKey(a, await fullMatchId(a, '2651ee46'));
      const res = await restPost(a, 'messages', { match_id: matchId, sender_id: a.userId, [textKey]: qaText('deleted') });
      if (res.ok()) for (const row of await res.json()) created.push(String(row.id));
      expect(res.status(), await res.text()).toBe(403);
    } finally {
      if (a) for (const id of created) await restDelete(a, `messages?id=eq.${id}`).catch(() => {});
      await saveSession(free, 'free');
    }
  });
});
